type Job<T> = () => Promise<T>;

export class JobQueue {
  private running = 0;
  private pending: Array<() => void> = [];
  private idleWaiters: Array<() => void> = [];

  constructor(private concurrency: number, private retries = 3) {}

  /** Enqueues a job; resolves with its result or rejects once retries are exhausted. */
  add<T>(job: Job<T>): Promise<T> {
    return new Promise<T>((resolve, reject) => {
      this.pending.push(async () => {
        try {
          resolve(await this.attempt(job));
        } catch (err) {
          reject(err);
        } finally {
          this.running--;
          this.next();
        }
      });
      this.next();
    });
  }

  /** Resolves when nothing is running or waiting. */
  onIdle(): Promise<void> {
    if (this.running === 0 && this.pending.length === 0) return Promise.resolve();
    return new Promise((resolve) => this.idleWaiters.push(resolve));
  }

  private async attempt<T>(job: Job<T>): Promise<T> {
    for (let i = 0; ; i++) {
      try {
        return await job();
      } catch (err) {
        if (i >= this.retries) throw err;
      }
    }
  }

  private next(): void {
    while (this.running < this.concurrency && this.pending.length > 0) {
      this.running++;
      this.pending.shift()!();
    }
    if (this.running === 0 && this.pending.length === 0) {
      this.idleWaiters.splice(0).forEach((resolve) => resolve());
    }
  }
}
